.params:not(:empty) {
  /* Full-width second header row. flex-basis 100% only works when header
     may wrap; shrink 0 so the chips are not crushed beside Load Trace. */
  flex: 1 0 100%;
  margin-left: 0;
  width: 100%;
}
/* Title + controls stay on row 1 (file-controls shrinks). Params uses the
   wrap row below so chips are not squeezed into a ~160px side column. */
header {
