const { chromium } = require('playwright');
const path = require('path');
const outDir = path.join(process.cwd(), 'web/usability');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  });

  async function measure(width, selectCompare) {
    const page = await browser.newPage({ viewport: { width, height: 800 } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    if (await page.locator('#uiTourSkip').isVisible({ timeout: 1000 }).catch(() => false)) {
      await page.locator('#uiTourSkip').click();
    }
    if (selectCompare) {
      for (const a of ['dots', 'dp', 'squish']) {
        await page.click(`.header-baseline .baseline-algo-pill[data-algo="${a}"]`);
      }
    }
    const idle = await page.evaluate(() => {
      const h1 = document.querySelector('header h1').getBoundingClientRect();
      const load = document.getElementById('loadBtn').getBoundingClientRect();
      const header = document.querySelector('header').getBoundingClientRect();
      return {
        headerH: Math.round(header.height),
        h1Top: Math.round(h1.top),
        loadTop: Math.round(load.top),
        titleBesideControls: Math.abs(h1.top - load.top) < 20,
      };
    });
    await page.selectOption('#traceSelect', '1');
    await page.click('#loadBtn');
    await page.waitForFunction(() => (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded'), { timeout: 120000 });
    await page.waitForTimeout(600);
    const loaded = await page.evaluate(() => {
      const bar = document.getElementById('paramsBar');
      const br = bar.getBoundingClientRect();
      const h1 = document.querySelector('header h1').getBoundingClientRect();
      const load = document.getElementById('loadBtn').getBoundingClientRect();
      const header = document.querySelector('header').getBoundingClientRect();
      const kids = [...bar.children];
      const tops = [...new Set(kids.map((el) => Math.round(el.getBoundingClientRect().top)))].sort((a,b)=>a-b);
      return {
        headerH: Math.round(header.height),
        paramsW: Math.round(br.width),
        paramsH: Math.round(br.height),
        chipRows: tops.length,
        h1Top: Math.round(h1.top),
        loadTop: Math.round(load.top),
        titleBesideControls: Math.abs(h1.top - load.top) < 20,
        scrollW: document.documentElement.scrollWidth,
        clientW: document.documentElement.clientWidth,
        text: bar.innerText.replace(/\s+/g, ' ').slice(0, 160),
      };
    });
    await page.close();
    return { idle, loaded };
  }

  for (const w of [1280, 900, 721]) {
    const none = await measure(w, false);
    const all = await measure(w, true);
    console.log(w, 'none', JSON.stringify(none));
    console.log(w, 'all3', JSON.stringify(all));
  }

  // refresh evidence shots
  for (const [w, h, name] of [[1280, 800, '1280'], [900, 800, '900']]) {
    const page = await browser.newPage({ viewport: { width: w, height: h } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    if (await page.locator('#uiTourSkip').isVisible({ timeout: 1000 }).catch(() => false)) await page.locator('#uiTourSkip').click();
    await page.selectOption('#traceSelect', '1');
    await page.click('#loadBtn');
    await page.waitForFunction(() => (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded'), { timeout: 120000 });
    await page.waitForTimeout(800);
    await page.screenshot({ path: path.join(outDir, `desktop-params-glosses-${name}-live.png`), fullPage: false });
    await page.close();
  }

  await browser.close();
  console.log('ok');
})().catch((e) => { console.error(e); process.exit(1); });
